package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct {
	TcSensor string
	TcF      decimal.Decimal
}

var WsEofFlag string = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)
var WsFreeze int64 = 0
var WsCount int64 = 0
var WsFEd string
var WsCEd string

var TempRecVar TempRec

var inputDone bool = false

func formatZZ9_9(v decimal.Decimal) string {
	// PIC ZZ9.9 width 5
	// scale 1
	scale := int32(1)
	// truncate toward zero to scale already stored? For MOVE we just format.
	// Ensure truncated? The source WS-F etc already has scale.
	// For positive numbers only (F is unsigned)
	neg := v.Sign() < 0
	if neg {
		v = v.Neg()
	}
	// overflow handling: keep low-order digits if integer part too large
	// integer digits = 3 (ZZ9)
	// width of integer part =3
	v = v.Truncate(int32(scale))
	// Extract integer and fractional
	// Use string representation
	// integer part
	intPart := v.IntPart() // truncates toward zero for positive
	// But for decimal with fraction, IntPart gives integer portion
	// fractional digit
	frac := v.Sub(decimal.NewFromInt(intPart)).Abs()
	// frac *10
	fracDigit := frac.Mul(decimal.NewFromInt(10)).IntPart() // 0-9

	// Overflow: keep low 3 integer digits
	intPartMod := intPart % 1000
	if intPartMod < 0 {
		intPartMod = -intPartMod
	}
	intStr := fmt.Sprintf("%03d", intPartMod)
	// Build picture: positions 0,1,2 are Z,Z,9
	pic := make([]byte, 3)
	for i := 0; i < 3; i++ {
		pic[i] = intStr[i]
	}
	// Apply Z suppression
	// Replace leading zeros with spaces until last digit before forced 9
	// For ZZ9: suppress zeros in positions 0,1 if following digits are all zero? Actually Z suppresses leading zero with space, but if entire integer part is zero, first two become spaces, last remains 0.
	suppress := true
	for i := 0; i < 2; i++ { // only first 2 are Z
		if suppress && pic[i] == '0' {
			// check if any non-zero later in integer part?
			// In COBOL Z suppression: leading zeros become spaces, but if all zeros then last forced 9 remains 0
			// So for ZZ9, if intStr == "000", positions 0,1 -> spaces, pos2 -> '0'
			// If intStr == "001", pos0->space, pos1->space, pos2->'1'
			// If intStr == "010", pos0->space, pos1->'1', pos2->'0'
			allZeroTail := true
			for k := i + 1; k < 3; k++ {
				if pic[k] != '0' {
					allZeroTail = false
					break
				}
			}
			if allZeroTail {
				// keep checking: actually 0 should become space if leading
				pic[i] = ' '
			} else {
				// if current is '0' and there is non-zero later, it should be space
				pic[i] = ' '
			}
		} else {
			suppress = false
		}
		if pic[i] != ' ' {
			suppress = false
		}
	}
	integerFormatted := string(pic)
	fracChar := byte('0' + fracDigit)
	result := integerFormatted + "." + string([]byte{fracChar})
	if neg {
		// not expected for F but handle
		result = "-" + result
	}
	return result
}

func format_MinusZZ9_99(v decimal.Decimal) string {
	// PIC -ZZ9.99 width 7: sign + ZZ9 + . + 99
	// sign: '-' if negative else ' ' (or fixed leading minus? spec says fixed leading minus sign -> same)
	scale := int32(2)
	vTrunc := v // already rounded to scale of WS-C; ensure we format with that scale
	neg := vTrunc.Sign() < 0
	absVal := vTrunc
	if neg {
		absVal = absVal.Neg()
	}
	absVal = absVal.Truncate(scale) // ensure truncated representation for formatting (already)
	// integer part 3 digits
	intPart := absVal.IntPart()
	intPartMod := intPart % 1000
	if intPartMod < 0 {
		intPartMod = -intPartMod
	}
	intStr := fmt.Sprintf("%03d", intPartMod)
	pic := []byte{intStr[0], intStr[1], intStr[2]}
	suppress := true
	for i := 0; i < 2; i++ {
		if suppress && pic[i] == '0' {
			// check if remaining integer digits are all zero? Still suppress
			pic[i] = ' '
		} else {
			suppress = false
			if pic[i] == ' ' {
				// already
			}
		}
		if pic[i] != ' ' {
			suppress = false
		}
	}
	integerFormatted := string(pic)
	// fractional 2 digits
	frac := absVal.Sub(decimal.NewFromInt(intPart)).Abs()
	// to avoid floating errors, get fractional as integer 0-99
	fracInt := frac.Mul(decimal.NewFromInt(100)).Truncate(0).IntPart()
	// due to truncation, need ensure 0-99
	if fracInt < 0 {
		fracInt = -fracInt
	}
	fracInt = fracInt % 100
	fracStr := fmt.Sprintf("%02d", fracInt)
	signChar := ' '
	if neg {
		signChar = '-'
	}
	return string([]byte{byte(signChar)}) + integerFormatted + "." + fracStr
}

func storeWsC(val decimal.Decimal) {
	// PIC S9(3)V99 scale 2, rounded already by COMPUTE ROUNDED
	// Round to scale 2 already done by caller, then truncate/overflow
	// Apply overflow: keep low-order digits
	scale := int32(2)
	rounded := val.Round(scale)
	// Check overflow truncation of high-order digits
	// Keep sign
	neg := rounded.Sign() < 0
	absVal := rounded.Abs()
	// integer part
	intPart := absVal.IntPart()
	frac := absVal.Sub(decimal.NewFromInt(intPart))
	// overflow integer digits: keep low 3 digits
	intPartMod := intPart % 1000
	newVal := decimal.NewFromInt(intPartMod).Add(frac)
	if neg {
		newVal = newVal.Neg()
	}
	WsC = newVal
}

func main() {
	// OPEN INPUT TEMP-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	var lines []string
	for scanner.Scan() {
		line := scanner.Text()
		lines = append(lines, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read error: %v\n", err)
		os.Exit(1)
	}
	idx := 0
	var currentLine string
	hasCurrent := false

	// helper read
	readPara := func() {
		if idx < len(lines) {
			raw := lines[idx]
			idx++
			// pad with spaces to 8 on right if shorter
			if len(raw) < 8 {
				raw = raw + strings.Repeat(" ", 8-len(raw))
			} else if len(raw) > 8 {
				raw = raw[:8]
			}
			currentLine = raw
			hasCurrent = true
			// parse TEMP-REC
			tcSensor := currentLine[0:4]
			tcFStr := currentLine[4:8] // 4 digits
			// PIC 9(3)V9 : digits only, implied 1 decimal
			// If contains spaces? treat as zero? But spec says digits
			tcFStrTrim := strings.TrimSpace(tcFStr)
			var n int64 = 0
			if tcFStrTrim != "" {
				// parse digits, ignore non-digit? assume digits
				var parsed int64 = 0
				for _, ch := range tcFStr {
					if ch >= '0' && ch <= '9' {
						parsed = parsed*10 + int64(ch-'0')
					} else if ch == ' ' {
						// treat as 0? but keep as digit
						parsed = parsed * 10
					}
				}
				n = parsed
			}
			dec := decimal.New(n, -1)
			TempRecVar = TempRec{
				TcSensor: tcSensor,
				TcF:      dec,
			}
			WsEofFlag = "N"
			inputDone = false
		} else {
			hasCurrent = false
			WsEofFlag = "Y"
			inputDone = true
		}
	}

	// MAIN-PARA
	readPara()
	for !inputDone {
		processPara(readPara)
	}
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	// WS-COUNT and WS-FREEZE are PIC 99 -> when displayed as numeric unedited? But in DISPLAY they are numeric items without edit.
	// In original COBOL, DISPLAY of PIC 99 will display as two characters? Typically numeric items display without leading zero suppression? But spec says unedited numeric DISPLAY prints zero-padded to digit count.
	// However test expects maybe without extra padding? Need replicate: For PIC 99, display zero-padded to 2 digits.
	// But the literal concatenation: DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	// In Go we need to format WS-COUNT as width 2 zero-padded? Let's check typical: PIC 99 DISPLAY would show e.g., "03". Need to decide.
	// We will format with %02d as per unedited numeric rule.
	countStr := fmt.Sprintf("%02d", WsCount)
	freezeStr := fmt.Sprintf("%02d", WsFreeze)
	// However many COBOL runtimes trim leading zeros for DISPLAY? Spec in this task says: "An unedited numeric DISPLAY item such as PIC 9(5) prints zero-padded to its digit count." So we must zero-pad.
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", countStr, freezeStr)
	_ = hasCurrent
}

func processPara(readPara func()) {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	diff := TempRecVar.TcF.Sub(decimal.NewFromInt(32))
	mul := diff.Mul(decimal.NewFromInt(5))
	div := mul.Div(decimal.NewFromInt(9))
	storeWsC(div)
	if WsC.Sign() < 0 {
		WsFreeze += 1
	}
	WsCount += 1
	WsFEd = formatZZ9_9(TempRecVar.TcF)
	WsCEd = format_MinusZZ9_99(WsC)
	fmt.Printf("%s %sF %sC\n", TempRecVar.TcSensor, WsFEd, WsCEd)
	readPara()
}
